function useReveal() {
  const ref = useRef(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      setShown(true);
      return;
    }
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setShown(true);
          io.disconnect();
        }
      },
      { threshold: 0.15 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, shown];
}

function Reveal({ children, delay = 0, className = "" }) {
  const [ref, shown] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        transition: `opacity 0.7s ease ${delay}ms, transform 0.7s cubic-bezier(.2,.8,.2,1) ${delay}ms`,
        opacity: shown ? 1 : 0,
        transform: shown ? "translateY(0)" : "translateY(18px)",
      }}
    >
      {children}
    </div>
  );
}

function EcgLine({ className = "" }) {
  const wave =
    "M0,40 L60,40 L74,40 L84,10 L96,68 L108,40 L120,40 L200,40 L214,40 L224,18 L236,58 L248,40 L260,40 L400,40";
  return (
    <div className={className} style={{ overflow: "hidden", width: "100%" }}>
      <div className="flex ecg-track" style={{ width: "200%" }}>
        {[0, 1].map((i) => (
          <svg
            key={i}
            viewBox="0 0 400 80"
            preserveAspectRatio="none"
            style={{ width: "50%", height: "100%", flexShrink: 0 }}
          >
            <path
              d={wave}
              fill="none"
              stroke={c.gold}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity="0.9"
            />
          </svg>
        ))}
      </div>
    </div>
  );
}

